module.exports = [{"id":"0009","name":"assisted chest dip (kneeling)","nameZh":"辅助双杠臂屈伸","equipment":"leverage machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0009-PAgTVaK.jpg","gifPath":"exercises/videos/0009-PAgTVaK.gif","instructionSteps":["将机器调整到您想要的高度，并将膝盖固定在垫子上。","手掌朝下，抓住手柄，双臂完全伸展。","弯曲肘部降低身体，直到上臂与地板平行。","暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"],"aliases":["辅助双杠","跪姿辅助臂屈伸"]},{"id":"0017","name":"assisted pull-up","nameZh":"辅助引体向上","equipment":"leverage machine","bodyPart":"back","target":"lats","imagePath":"exercises/images/0017-kiJ4Z2K.jpg","gifPath":"exercises/videos/0017-kiJ4Z2K.gif","instructionSteps":["将机器调整至您所需的体重和高度设置。","正手握住手柄，握距略宽于肩宽。","双臂完全伸展，双脚离开地面。","收紧背部肌肉，将身体拉向手柄，保持肘部靠近身体。","继续拉，直到下巴位于手柄上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"aliases":["辅助引体","辅助正手引体"]},{"id":"0019","name":"assisted triceps dip (kneeling)","nameZh":"辅助肱三头肌臂屈伸 (跪姿)","equipment":"leverage machine","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0019-J60bN17.jpg","gifPath":"exercises/videos/0019-J60bN17.gif","instructionSteps":["将机器调整到您想要的重量和高度。","跪在面向机器的垫子上，双手握住手柄。","弯曲肘部降低身体，保持背部挺直并靠近机器。","在底部暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"],"aliases":["辅助臂屈伸"]},{"id":"0025","name":"barbell bench press","nameZh":"杠铃卧推","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0025-EIeI8Vf.jpg","gifPath":"exercises/videos/0025-EIeI8Vf.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","将杠铃慢慢降低到胸部，保持肘部内收。","当杠铃触及胸部时暂停片刻。","伸展双臂，将杠铃推回到起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0027","name":"barbell bent over row","nameZh":"杠铃俯身划船","equipment":"barbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0027-eZyBC3j.jpg","gifPath":"exercises/videos/0027-eZyBC3j.gif","instructionSteps":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","臀部向前弯曲，同时保持背部挺直、挺胸。","正手握住杠铃，双手间距略宽于肩宽。","通过收缩肩胛骨并挤压背部肌肉，将杠铃拉向下胸部。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0030","name":"barbell close-grip bench press","nameZh":"杠铃窄距卧推","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0030-J6Dx1Mu.jpg","gifPath":"exercises/videos/0030-J6Dx1Mu.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","紧紧握住杠铃，握距略窄于肩宽。","松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"aliases":["窄距卧推"]},{"id":"0031","name":"barbell curl","nameZh":"杠铃弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0031-25GPyDY.jpg","gifPath":"exercises/videos/0031-25GPyDY.gif","instructionSteps":["站直，双脚分开与肩同宽，反手握住杠铃，手掌朝前。","保持肘部靠近躯干，在弯举哑铃时呼气，同时收缩二头肌。","继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢开始将杠铃放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0032","name":"barbell deadlift","nameZh":"杠铃硬拉","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0032-ila4NZS.jpg","gifPath":"exercises/videos/0032-ila4NZS.gif","instructionSteps":["双脚分开与肩同宽站立，杠铃放在你面前的地面上。","弯曲膝盖并以臀部为铰链，降低躯干，正手握住杠铃，双手分开略宽于肩宽。","当你通过脚后跟将杠铃抬离地面时，保持背部挺直，胸部抬起，伸展臀部和膝盖。","当你站直时，挤压你的臀部并保持你的核心参与。","弯曲臀部和膝盖，将杠铃放回地面，保持背部挺直。","重复所需的重复次数。"],"aliases":[]},{"id":"0042","name":"barbell front squat","nameZh":"杠铃前蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0042-zG0zs85.jpg","gifPath":"exercises/videos/0042-zG0zs85.gif","instructionSteps":["首先站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在肩膀前面，将其放在锁骨和肩膀上。","当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0043","name":"barbell full squat","nameZh":"杠铃深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0043-qXTaZnJ.jpg","gifPath":"exercises/videos/0043-qXTaZnJ.gif","instructionSteps":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","当你开始降低身体时，启动你的核心并保持胸部挺直。","弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。","放低身体，直到大腿与地面平行或稍低于地面。","保持膝盖与脚趾对齐，并将重量放在脚后跟上。","通过脚后跟站起来，伸展臀部和膝盖。","重复所需的重复次数。"],"aliases":[]},{"id":"0046","name":"barbell hack squat","nameZh":"杠铃哈克深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0046-5VCj6iH.jpg","gifPath":"exercises/videos/0046-5VCj6iH.gif","instructionSteps":["首先站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在腿后面，将其放在大腿上部。","弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。","继续降低，直到大腿与地面平行，或者尽可能低。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0047","name":"barbell incline bench press","nameZh":"杠铃上斜卧推","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0047-3TZduzM.jpg","gifPath":"exercises/videos/0047-3TZduzM.gif","instructionSteps":["设置一个 45 度角的上斜凳。","躺在长凳上，双脚平放在地上。","正手握住杠铃，握距略宽于肩宽。","松开杠铃并将其缓慢降低至胸部，保持肘部呈 45 度角。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0060","name":"barbell lying triceps extension skull crusher","nameZh":"仰卧臂屈伸","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0060-h8LFzo9.jpg","gifPath":"exercises/videos/0060-h8LFzo9.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，头放在长凳的末端。","正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。","保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。","当杠铃位于前额上方时暂停片刻，然后将手臂向后伸展至起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0085","name":"barbell romanian deadlift","nameZh":"罗马尼亚硬拉","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0085-wQ2c4XD.jpg","gifPath":"exercises/videos/0085-wQ2c4XD.gif","instructionSteps":["站立，双脚分开与肩同宽，脚趾指向前方。","正手握住杠铃，双手分开略宽于肩宽。","弯曲臀部，保持背部挺直，膝盖稍微弯曲。","将杠铃向地面降低，使其靠近身体。","当你降低杠铃时，感受腿筋的拉伸。","一旦感觉到腿筋拉伸，就将臀部向前推并站直。","在动作的最高点挤压臀部。","将杠铃放回起始位置，然后重复所需的重复次数。"],"aliases":[]},{"id":"0088","name":"barbell seated calf raise","nameZh":"杠铃坐姿提踵","equipment":"barbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0088-ktsFQAZ.jpg","gifPath":"exercises/videos/0088-ktsFQAZ.gif","instructionSteps":["坐在长凳上，双脚平放在地板上，杠铃放在大腿上。","将脚掌放在升高的平台上，例如木块或台阶。","将杠铃放在大腿上，并用手牢牢握住它。","保持背部挺直，核心收紧，伸展脚踝，将脚后跟抬离地面。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0091","name":"barbell seated overhead press","nameZh":"杠铃坐姿过头推举","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0091-kTbSH9h.jpg","gifPath":"exercises/videos/0091-kTbSH9h.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，杠铃间距略宽于肩宽。","将杠铃从架子上提起，并将其置于与肩同高的位置，肘部弯曲，手掌朝前。","充分伸展双臂，将杠铃压过头顶。","在顶部停顿片刻，然后慢慢将杠铃放回肩部水平。","重复所需的重复次数。"],"aliases":["坐姿杠铃推肩"]},{"id":"0092","name":"barbell seated overhead triceps extension","nameZh":"杠铃过头臂屈伸","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0092-5uFK1xr.jpg","gifPath":"exercises/videos/0092-5uFK1xr.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，双手与肩同宽，并将其举过头顶。","弯曲肘部，将杠铃降低到脑后，保持上臂靠近头部。","暂停片刻，然后伸展双臂将杠铃举回起始位置。","重复所需的重复次数。"],"aliases":["杠铃颈后臂屈伸"]},{"id":"0117","name":"barbell sumo deadlift","nameZh":"杠铃相扑硬拉","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0117-KgI0tqW.jpg","gifPath":"exercises/videos/0117-KgI0tqW.gif","instructionSteps":["站立，双脚分开比肩宽，脚趾朝外。","将杠铃放在您面前的地面上，位于双脚之间的中心。","弯曲膝盖，降低臀部，保持背部挺直，挺胸，用正手握法抓住杠铃。","启动你的核心并通过你的脚后跟发力，将杠铃抬离地面，同时伸展你的臀部和膝盖。","当你举起时，保持胸部挺直，背部挺直，向前推动臀部以充分锻炼臀部。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置，在整个动作过程中保持控制。","重复所需的重复次数。"],"aliases":[]},{"id":"0120","name":"barbell upright row","nameZh":"杠铃直立划船","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0120-UDlhcO8.jpg","gifPath":"exercises/videos/0120-UDlhcO8.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。","让杠铃悬挂在大腿前面，双臂完全伸展。","保持背部挺直，核心收紧，呼气，将杠铃笔直向上举向下巴，用肘部引导。","在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0165","name":"cable hammer curl (with rope)","nameZh":"绳索锤式弯举","equipment":"cable","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0165-HPlPoQA.jpg","gifPath":"exercises/videos/0165-HPlPoQA.gif","instructionSteps":["站直，双脚分开与肩同宽，膝盖稍微弯曲。","双手握住缆绳附件，手掌相对，手臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续提升缆绳附件，直到您的二头肌完全收缩并且绳索与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将缆绳附件降低回起始位置。","重复所需的重复次数。"],"aliases":["绳索绳柄锤式弯举"]},{"id":"0171","name":"cable incline fly","nameZh":"绳索上斜飞鸟","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0171-tBWXbIT.jpg","gifPath":"exercises/videos/0171-tBWXbIT.gif","instructionSteps":["将电缆机调整至较低位置并安装手柄。","坐在倾斜的长凳上，背部靠在垫子上，双脚平放在地板上。","正手握住手柄，并将双臂伸直至身前。","保持肘部轻微弯曲，以受控的动作向两侧张开双臂。","在完全伸展位置停顿片刻，然后慢慢回到起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0175","name":"cable kneeling crunch","nameZh":"绳索卷腹","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0175-WW95auq.jpg","gifPath":"exercises/videos/0175-WW95auq.gif","instructionSteps":["将绳索手柄连接到高滑轮上，然后面向远离机器的方向跪下。","双手握住绳柄，将其放在脑后，肘部向两侧伸出。","保持臀部不动，弯曲腰部并将躯干向大腿方向挤压。","在底部停顿片刻，然后慢慢回到起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0178","name":"cable lateral raise","nameZh":"绳索侧平举","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0178-goJ6ezq.jpg","gifPath":"exercises/videos/0178-goJ6ezq.gif","instructionSteps":["双脚分开与肩同宽站立，并用正手握住电缆手柄。","保持双臂伸直，核心肌群参与。","将手臂向两侧举起，直到与地板平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0188","name":"cable middle fly","nameZh":"绳索夹胸","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0188-xLYSdtg.jpg","gifPath":"exercises/videos/0188-xLYSdtg.gif","instructionSteps":["将电缆连接到电缆机两侧胸部高度处。","站在机器的中央，一只脚稍微在另一只脚前面。","正手握住手柄，并将手臂向两侧伸展。","保持肘部轻微弯曲并保持轻微前倾。","收紧胸部肌肉，并以扫过的动作将手臂向前伸。","在中心停顿片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"],"aliases":["龙门架夹胸"]},{"id":"0194","name":"cable overhead triceps extension (rope attachment)","nameZh":"绳索过头臂屈伸","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0194-2IxROQ1.jpg","gifPath":"exercises/videos/0194-2IxROQ1.gif","instructionSteps":["将绳索连接到高处的缆绳机上。","背对机器站立，双脚与肩同宽。","双手抓住绳子，掌心相对，将双手举过头顶。","保持上臂靠近头部，肘部向前。","弯曲肘部，慢慢将绳子降低到头后。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0196","name":"cable pull through (with rope)","nameZh":"绳索穿腿后拉","equipment":"cable","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0196-OM46QHm.jpg","gifPath":"exercises/videos/0196-OM46QHm.gif","instructionSteps":["背对缆绳机站立，双脚与肩同宽。","双手抓住绳索附件并向前迈一步，在绳索中产生张力。","弯曲臀部并降低上身直至与地面平行，保持背部挺直。","启动臀肌和腿筋，将身体拉回到起始位置。","重复所需的重复次数。"],"aliases":["绳索拉裆"]},{"id":"0198","name":"cable pulldown","nameZh":"高位下拉","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0198-RVwzP10.jpg","gifPath":"exercises/videos/0198-RVwzP10.gif","instructionSteps":["调整拉索下拉机，使座椅处于舒适的高度并固定护膝。","坐在座位上，背部挺直，双脚平放在地面上。","正手握住电缆杆，握距略宽于肩宽。","稍微向后倾斜并启动你的核心。","将电缆杆向下拉向胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。","重复所需的重复次数。"],"aliases":["下拉"]},{"id":"0201","name":"cable pushdown","nameZh":"绳索下压","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0201-3ZflifB.jpg","gifPath":"exercises/videos/0201-3ZflifB.gif","instructionSteps":["将直杆连接到高滑轮电缆机上。","面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，双手与肩同宽。","保持肘部靠近身体两侧，上臂保持静止。","呼气并将杠铃向下推，直到肘部完全伸展。","暂停片刻，然后吸气，慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"],"aliases":["直杆下压"]},{"id":"0213","name":"cable seated high row (v-bar)","nameZh":"绳索 V 杆划船","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0213-pwt0pnM.jpg","gifPath":"exercises/videos/0213-pwt0pnM.gif","instructionSteps":["坐在缆绳机上，双脚平放在地板上，膝盖稍微弯曲。","正手握住 V 形杆附件，手掌相对，双手与肩同宽。","保持背部挺直，并从臀部稍微向前倾斜。","通过收缩肩胛骨并挤压背部肌肉，将 V 形杆拉向躯干。","在收缩的顶峰停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"aliases":["V 杆高位划船"]},{"id":"0216","name":"cable seated shoulder internal rotation","nameZh":"绳索坐姿肩内旋","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0216-YPoVrBi.jpg","gifPath":"exercises/videos/0216-YPoVrBi.gif","instructionSteps":["坐在长凳或椅子上，面向电缆机，双脚平放在地面上。","握住电缆手柄，手臂在身前伸直，与地面平行。","保持肘部稍微弯曲，肩胛骨向后和向下拉。","慢慢向内旋转手臂，将电缆手柄拉向身体中心。","动作结束时暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换臂。"],"aliases":["坐姿绳索内旋","肩袖内旋"]},{"id":"0223","name":"cable side crunch","nameZh":"绳索侧卷腹","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0223-q2ADGqV.jpg","gifPath":"exercises/videos/0223-q2ADGqV.gif","instructionSteps":["将电缆手柄连接到低滑轮上并站在机器旁边。","用距离机器最远的手抓住手柄，并将另一只手放在臀部上。","双脚分开与肩同宽，膝盖稍微弯曲。","收紧腹肌，腰部向侧面弯曲，将肘部向下拉向臀部。","在底部停顿片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换边。"],"aliases":["侧向绳索卷腹"]},{"id":"0226","name":"cable standing crunch","nameZh":"站姿绳索卷腹","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0226-jpgqxiS.jpg","gifPath":"exercises/videos/0226-jpgqxiS.gif","instructionSteps":["将电缆手柄连接到高滑轮上，并背对机器站立。","双手握住手柄并将其放在脑后，保持肘部弯曲。","双脚分开与肩同宽站立，膝盖稍微弯曲。","保持腹肌收紧，呼气，将躯干压向膝盖，将肘部拉向大腿。","在动作底部暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"],"aliases":["龙门架站姿卷腹"]},{"id":"0227","name":"cable standing fly","nameZh":"绳索站姿飞鸟","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0227-Pr9Rhf4.jpg","gifPath":"exercises/videos/0227-Pr9Rhf4.gif","instructionSteps":["将手柄连接到胸部高度的电缆上。","双脚分开与肩同宽站立，背对缆绳机。","正手握住手柄，手掌朝前。","稍微向前一步以在缆绳中产生张力。","在整个练习过程中保持核心参与并保持背部挺直。","肘部稍微弯曲，慢慢地将双臂向前并拢在胸前。","在运动的最高点挤压胸部肌肉。","慢慢扭转动作，将手臂恢复到起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0228","name":"cable standing hip extension","nameZh":"绳索后踢腿","equipment":"cable","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0228-Kpajagk.jpg","gifPath":"exercises/videos/0228-Kpajagk.gif","instructionSteps":["将电缆连接到低滑轮上，并背对机器站立。","将电缆绕在脚踝上，双脚分开与肩同宽站立。","在整个练习过程中保持核心参与并保持背部挺直。","慢慢地将腿向后伸直，在动作的最高点挤压臀部。","暂停片刻，然后回到起始位置。","重复所需的重复次数。","换边并用另一条腿重复。"],"aliases":["绳索髋伸展"]},{"id":"0233","name":"cable standing rear delt row (with rope)","nameZh":"绳索面拉","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0233-ZfyAGhK.jpg","gifPath":"exercises/videos/0233-ZfyAGhK.gif","instructionSteps":["面向缆绳机站立，双脚与肩同宽。","用双手握住电缆附件，手掌相对，然后后退以在电缆中产生张力。","保持背部挺直，核心肌群参与。","将电缆拉向您的身体，将肩胛骨挤压在一起。","在运动的最高点停顿片刻，然后慢慢松开绳索回到起始位置。","重复所需的重复次数。"],"aliases":["面拉","绳索肩胛后拉"]},{"id":"0235","name":"cable standing shoulder external rotation","nameZh":"绳索站姿肩外旋","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0235-FWdVhcW.jpg","gifPath":"exercises/videos/0235-FWdVhcW.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","将手臂伸向前方，与地面平行，握住电缆手柄。","保持肘部稍微弯曲，肩胛骨向后拉。","慢慢地向外旋转手臂，远离身体，同时保持肘部处于同一位置。","动作结束时暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"],"aliases":["绳索肩外旋","肩袖外旋"]},{"id":"0238","name":"cable straight arm pulldown","nameZh":"绳索直臂下拉","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0238-x69MAlq.jpg","gifPath":"exercises/videos/0238-x69MAlq.gif","instructionSteps":["将直杆连接到缆绳机的高滑轮上。","面向机器站立，双脚分开与肩同宽。","正手握住杠铃，保持手臂伸直，手掌朝下。","收紧背阔肌并将杠铃向下拉向大腿，在整个运动过程中保持手臂伸直。","在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0243","name":"cable twist","nameZh":"绳索转体","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0243-aVs3BR3.jpg","gifPath":"exercises/videos/0243-aVs3BR3.gif","instructionSteps":["双脚分开与肩同宽站立，面向绳索机。","双手握住电缆手柄于胸前，保持双臂略微弯曲。","启动你的核心并将你的躯干向右扭转，将电缆拉过你的身体。","动作结束时暂停片刻，感受腹肌和斜肌的收缩。","缓慢返回起始位置，抵抗绳索的拉力。","向左侧重复该动作。","继续交替进行所需的重复次数。"],"aliases":[]},{"id":"0246","name":"cable upright row","nameZh":"绳索直立划船","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0246-cALKspW.jpg","gifPath":"exercises/videos/0246-cALKspW.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲，并用正手握住电缆附件。","在整个练习过程中保持背部挺直，核心肌群参与其中。","用肘部引导，将电缆附件笔直向上拉向下巴。","在顶部暂停片刻，将肩胛骨挤压在一起。","缓慢地将电缆附件放回起始位置。","重复所需的重复次数。"],"aliases":["龙门架直立划船"]},{"id":"0251","name":"chest dip","nameZh":"双杠臂屈伸","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0251-9WTm7dq.jpg","gifPath":"exercises/videos/0251-9WTm7dq.gif","instructionSteps":["将自己置于双杠上，双臂完全伸展，身体伸直。","弯曲肘部，降低身体，直到肩膀低于肘部。","伸直手臂，将自己推回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0274","name":"crunch floor","nameZh":"卷腹","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0274-TFqbd8t.jpg","gifPath":"exercises/videos/0274-TFqbd8t.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，将肩膀抬离地面，向前向膝盖弯曲。","在顶部停顿片刻，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0276","name":"dead bug","nameZh":"死虫式","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0276-iny3m5y.jpg","gifPath":"exercises/videos/0276-iny3m5y.gif","instructionSteps":["平躺，双臂伸向天花板。","弯曲膝盖，将双腿抬离地面，使臀部和膝盖形成 90 度角。","接合你的核心和下背部，将你的下背部压入地面。","慢慢地将右臂和左腿放低至地面，保持它们伸直并悬停在地板上方。","暂停片刻，然后回到起始位置。","用左臂和右腿重复该动作。","继续交替进行所需的重复次数。"],"aliases":["死虫"]},{"id":"0289","name":"dumbbell bench press","nameZh":"哑铃卧推","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0289-SpYC0Kp.jpg","gifPath":"exercises/videos/0289-SpYC0Kp.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","双手各握一个哑铃，手掌朝前，双臂伸至胸部上方。","慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。","暂停片刻，然后将哑铃推回起始位置，完全伸展双臂。","重复所需的重复次数。"],"aliases":[]},{"id":"0293","name":"dumbbell bent over row","nameZh":"哑铃俯身划船","equipment":"dumbbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0293-BJ0Hz5L.jpg","gifPath":"exercises/videos/0293-BJ0Hz5L.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个哑铃，手掌朝向身体。","臀部向前弯曲，保持背部挺直，核心肌群参与。","让你的手臂垂直垂向地板，肘部稍微弯曲。","将哑铃拉向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"aliases":["哑铃划船"]},{"id":"0294","name":"dumbbell biceps curl","nameZh":"哑铃弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0294-NbVPDMW.jpg","gifPath":"exercises/videos/0294-NbVPDMW.gif","instructionSteps":["站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0297","name":"dumbbell concentration curl","nameZh":"哑铃集中弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0297-gvsWLQw.jpg","gifPath":"exercises/videos/0297-gvsWLQw.gif","instructionSteps":["坐在长凳上，双腿分开，一只手拿着哑铃，肘部放在大腿内侧。","完全伸展手臂并用反手握住哑铃。","保持上臂静止，呼气并将重量向上弯向肩膀，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"],"aliases":["集中弯举"]},{"id":"0308","name":"dumbbell fly","nameZh":"哑铃飞鸟","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0308-yz9nUhF.jpg","gifPath":"exercises/videos/0308-yz9nUhF.gif","instructionSteps":["平躺在长凳上，双手各握一个哑铃，手掌相对。","将手臂伸直越过胸部，肘部稍微弯曲。","保持肘部轻微弯曲，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。","暂停片刻，然后反转动作，将哑铃拉回到起始位置。","重复所需的重复次数。"],"aliases":["平板哑铃飞鸟"]},{"id":"0310","name":"dumbbell front raise","nameZh":"哑铃前平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0310-3eGE2JC.jpg","gifPath":"exercises/videos/0310-3eGE2JC.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。","保持双臂伸直，呼气并将哑铃举至身前，直至与肩齐平。","在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"aliases":["前平举"]},{"id":"0313","name":"dumbbell hammer curl","nameZh":"锤式弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0313-slDvUAU.jpg","gifPath":"exercises/videos/0313-slDvUAU.gif","instructionSteps":["站直，双手各持一个哑铃，手掌朝向躯干。","保持肘部靠近躯干，并旋转手掌，直到手掌朝前。","这将是您的起始位置。","现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。","继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","然后，吸气并慢慢开始将哑铃放回起始位置。","重复建议的重复次数。"],"aliases":["哑铃锤式弯举"]},{"id":"0314","name":"dumbbell incline bench press","nameZh":"上斜哑铃卧推","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0314-ns0SIbU.jpg","gifPath":"exercises/videos/0314-ns0SIbU.gif","instructionSteps":["设置一个 45 度角的上斜凳。","坐在长凳上，双脚平放在地上，背部紧贴长凳。","双手各握一个哑铃，掌心向前，将哑铃举至肩高。","慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。","将哑铃推回起始位置，充分伸展手臂。","重复所需的重复次数。"],"aliases":["上斜哑铃推举"]},{"id":"0315","name":"dumbbell incline biceps curl","nameZh":"哑铃上斜弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0315-F3xgbjF.jpg","gifPath":"exercises/videos/0315-F3xgbjF.gif","instructionSteps":["坐在上斜凳上，双手各握一个哑铃，手掌朝前，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0319","name":"dumbbell incline fly","nameZh":"哑铃上斜飞鸟","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0319-ESOd5Pl.jpg","gifPath":"exercises/videos/0319-ESOd5Pl.gif","instructionSteps":["将上斜凳设置为 45 度角。","坐在长凳上，双手各握一个哑铃，手掌相对。","仰卧在长凳上，将哑铃推至起始位置，位于胸部正上方。","将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。","暂停片刻，然后挤压胸部肌肉，将哑铃拉回起始位置。","重复所需的重复次数。"],"aliases":["上斜哑铃飞鸟"]},{"id":"0333","name":"dumbbell kickback","nameZh":"哑铃后摆臂屈伸","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0333-W6PxUkg.jpg","gifPath":"exercises/videos/0333-W6PxUkg.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将上臂靠近身体两侧，肘部弯曲成 90 度角。","将手臂向后伸直，在动作的最高点挤压三头肌。","暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"aliases":["哑铃回扣"]},{"id":"0334","name":"dumbbell lateral raise","nameZh":"哑铃侧平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0334-DsgkuIt.jpg","gifPath":"exercises/videos/0334-DsgkuIt.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","保持背部挺直并启动核心肌群。","将手臂向两侧抬起，直到与地板平行，保持肘部稍微弯曲。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0336","name":"dumbbell lunge","nameZh":"哑铃箭步蹲","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0336-RRWFUcw.jpg","gifPath":"exercises/videos/0336-RRWFUcw.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","右脚向前迈出一步，将身体降低至弓步位置。","降低身体时保持背部挺直、挺胸。","推动右脚跟回到起始位置。","左腿重复上述动作。","交替腿进行所需的重复次数。"],"aliases":["箭步蹲","哑铃行走箭步"]},{"id":"0372","name":"dumbbell preacher curl","nameZh":"哑铃牧师凳弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0372-jivWf8n.jpg","gifPath":"exercises/videos/0372-jivWf8n.gif","instructionSteps":["坐在牧师弯举凳上，上臂放在垫子上，胸部靠在垫子上。","每只手握住一个哑铃，手掌朝上，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0381","name":"dumbbell rear lunge","nameZh":"反向箭步蹲","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0381-SSsBDwB.jpg","gifPath":"exercises/videos/0381-SSsBDwB.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","右脚向后退一步，将身体降低至弓步位置。","弯曲左膝并降低身体，直到左大腿与地面平行。","暂停片刻，然后推动左脚跟回到起始位置。","在另一侧重复，左脚向后退一步。"],"aliases":["后撤箭步蹲","哑铃反向箭步"]},{"id":"0405","name":"dumbbell seated shoulder press","nameZh":"哑铃推举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0405-znQUdHY.jpg","gifPath":"exercises/videos/0405-znQUdHY.gif","instructionSteps":["坐在长凳上，每只手各拿一个哑铃，放在大腿上。","将哑铃举至肩高，手掌朝前。","向上推哑铃，直到手臂完全伸过头顶。","在顶部停顿片刻，然后慢慢将哑铃放回肩部高度。","重复所需的重复次数。"],"aliases":["哑铃推肩","坐姿哑铃推肩"]},{"id":"0407","name":"dumbbell side bend","nameZh":"站姿哑铃侧屈","equipment":"dumbbell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0407-IpONWYv.jpg","gifPath":"exercises/videos/0407-IpONWYv.gif","instructionSteps":["站直，双脚分开与肩同宽，一手握住哑铃，让它垂在身侧。","保持背部挺直，核心肌群参与，慢慢地将腰部向哑铃的另一侧侧弯，在舒适的范围内尽可能降低重量。","暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换边重复。"],"aliases":["哑铃体侧屈"]},{"id":"0417","name":"dumbbell standing calf raise","nameZh":"哑铃站姿提踵","equipment":"dumbbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0417-dPmaUaU.jpg","gifPath":"exercises/videos/0417-dPmaUaU.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","用小腿将脚跟抬离地面，尽可能高。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0431","name":"dumbbell step-up","nameZh":"哑铃登阶","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0431-aXtJhlg.jpg","gifPath":"exercises/videos/0431-aXtJhlg.gif","instructionSteps":["站在长凳或台阶前，每只手各握一个哑铃，手掌朝向身体。","将右脚放在长凳或台阶上，确保整个脚与表面接触。","推动右脚跟，将身体抬起到长凳或台阶上，伸直右腿。","将左脚放在长凳或台阶上，完全直立。","左脚向后退一步，然后是右脚，回到起始位置。","重复所需的重复次数，然后换腿。"],"aliases":["登阶"]},{"id":"0432","name":"dumbbell stiff leg deadlift","nameZh":"哑铃直腿硬拉","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0432-5eLRITT.jpg","gifPath":"exercises/videos/0432-5eLRITT.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，正握。","保持背部挺直，核心收紧，铰接臀部并将哑铃向地面降低，让膝盖稍微弯曲。","降低哑铃，直到感觉到腿筋拉伸，然后挤压臀肌并通过脚后跟推回到起始位置。","重复所需的重复次数。"],"aliases":["直腿硬拉"]},{"id":"0437","name":"dumbbell upright row","nameZh":"哑铃直立划船","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0437-ainizkb.jpg","gifPath":"exercises/videos/0437-ainizkb.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，正握。","让哑铃悬挂在大腿前面，双臂完全伸展。","保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。","在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0447","name":"ez barbell curl","nameZh":"曲杠弯举","equipment":"ez barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0447-6TG6x2w.jpg","gifPath":"exercises/videos/0447-6TG6x2w.gif","instructionSteps":["站直，双脚分开与肩同宽，反手握住 ez 杠铃，手掌朝上。","在整个运动过程中，保持肘部靠近躯干，上臂保持静止。","当你将杠铃向肩膀方向卷曲时呼气，收缩二头肌。","在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"aliases":["EZ 杠弯举","曲杆弯举"]},{"id":"0464","name":"front plank with twist","nameZh":"平板支撑带转体","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0464-CosupLu.jpg","gifPath":"exercises/videos/0464-CosupLu.gif","instructionSteps":["从高平板支撑位置开始，双手直接放在肩膀下方，身体从头到脚成一条直线。","调动你的核心和臀部以保持稳定的位置。","将躯干向右旋转，抬起右臂并向天花板延伸。","扭转时保持臀部和腿部稳定。","保持片刻，然后回到起始位置。","在左侧重复扭转。","继续交替进行所需的重复次数。"],"aliases":["带转体平板支撑"]},{"id":"0472","name":"hanging leg raise","nameZh":"悬垂举腿","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0472-I3tsCnC.jpg","gifPath":"exercises/videos/0472-I3tsCnC.gif","instructionSteps":["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。","启动你的核心并将双腿抬起到你面前，保持伸直。","继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"],"aliases":["悬垂抬腿","悬挂抬脚"]},{"id":"0475","name":"hanging straight leg raise","nameZh":"悬垂直腿举腿","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0475-4Ml7QFO.jpg","gifPath":"exercises/videos/0475-4Ml7QFO.gif","instructionSteps":["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。","启动你的核心并将双腿抬起到你面前，保持伸直。","继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"],"aliases":["悬垂直腿抬腿"]},{"id":"0489","name":"hyperextension","nameZh":"山羊挺身","equipment":"body weight","bodyPart":"back","target":"spine","imagePath":"exercises/images/0489-zhMwOwE.jpg","gifPath":"exercises/videos/0489-zhMwOwE.gif","instructionSteps":["调整过度伸展凳，使大腿上部放在垫子上并且双脚固定。","双臂交叉放在胸前或将双手放在脑后。","将上半身压向地面，同时保持背部挺直。","在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。","重复所需的重复次数。"],"aliases":[]},{"id":"0493","name":"incline push-up","nameZh":"上斜俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0493-B1EVP9F.jpg","gifPath":"exercises/videos/0493-B1EVP9F.gif","instructionSteps":["将双手放在较高的表面上，例如长凳或台阶上，双手之间的距离略宽于肩宽。","将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。","弯曲肘部，将胸部向升高的表面降低，保持身体呈一条直线。","在底部暂停片刻，然后伸直手臂将自己推回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0499","name":"inverted row","nameZh":"反向划船","equipment":"body weight","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0499-bZGHsAZ.jpg","gifPath":"exercises/videos/0499-bZGHsAZ.gif","instructionSteps":["在腰部高度设置一个杠铃或使用悬挂训练器。","面向杠铃或悬吊训练器站立，双脚分开与肩同宽。","正手握住杠铃或手柄，握距略宽于肩宽。","向后倾斜，保持身体挺直，脚后跟着地。","将胸部拉向杠铃或手柄，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢降低回到起始位置。","重复所需的重复次数。"],"aliases":["澳式引体"]},{"id":"0507","name":"jackknife sit-up","nameZh":"折刀式仰卧起坐","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0507-mbkgB44.jpg","gifPath":"exercises/videos/0507-mbkgB44.gif","instructionSteps":["平躺，双腿伸展，双臂举过头顶。","启动你的核心，同时抬起双腿和上半身，将双手伸向脚趾。","在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。","重复所需的重复次数。"],"aliases":["折刀起坐"]},{"id":"0573","name":"lever back extension","nameZh":"器械山羊挺身","equipment":"leverage machine","bodyPart":"back","target":"spine","imagePath":"exercises/images/0573-rUXfn3R.jpg","gifPath":"exercises/videos/0573-rUXfn3R.gif","instructionSteps":["调整机器以适合您的身体尺寸和运动范围。","坐在机器上，背部靠在垫子上，双脚固定。","将手放在手柄或握杆上。","启动你的核心并慢慢向前倾斜，让你的背部稍微弯曲。","在底部位置暂停片刻，感觉下背部有拉伸感。","使用背部肌肉，慢慢将躯干抬回到起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0575","name":"lever bicep curl","nameZh":"器械弯举","equipment":"leverage machine","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0575-q6y3OhV.jpg","gifPath":"exercises/videos/0575-q6y3OhV.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在垫子上。","反手握住手柄，手掌朝上，肘部靠近身体两侧。","呼气并向上弯曲手柄，收缩二头肌。","在动作的最高点暂停片刻，挤压你的二头肌。","吸气，慢慢将手柄放回起始位置，充分伸展双臂。","重复所需的重复次数。"],"aliases":["器械二头弯举"]},{"id":"0576","name":"lever chest press","nameZh":"器械推胸","equipment":"leverage machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0576-DOoWcnA.jpg","gifPath":"exercises/videos/0576-DOoWcnA.gif","instructionSteps":["调整座椅高度，将自己放在机器上，背部平放在垫子上。","正手握住手柄，肘部呈 90 度角。","向前推动手柄，直到手臂完全伸展，运动过程中呼气。","动作结束时短暂暂停，然后慢慢回到起始位置，同时吸气。","重复所需的重复次数。"],"aliases":[]},{"id":"0584","name":"lever lateral raise","nameZh":"器械侧平举","equipment":"leverage machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0584-dRTfGZT.jpg","gifPath":"exercises/videos/0584-dRTfGZT.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在垫子上。","正手握住手柄并保持手臂伸直。","呼气并将手臂向两侧抬起，直到与地板平行。","在顶部停顿片刻，然后吸气，慢慢将手臂放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0585","name":"lever leg extension","nameZh":"器械腿屈伸","equipment":"leverage machine","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0585-my33uHU.jpg","gifPath":"exercises/videos/0585-my33uHU.gif","instructionSteps":["调整机器的座椅高度和靠背以适合您的身体。","坐在机器上，背部靠在靠背上，双脚放在脚垫上。","抓住手柄或侧杆以保持稳定性。","伸直膝盖，举起重物，向前伸展双腿。","在顶部暂停片刻，然后慢慢将重量放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0586","name":"lever lying leg curl","nameZh":"俯卧腿弯举","equipment":"leverage machine","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0586-17lJ1kr.jpg","gifPath":"exercises/videos/0586-17lJ1kr.gif","instructionSteps":["调整机器以适合您的身体并选择所需的重量。","面朝下躺在机器上，双腿伸直，脚跟靠在带衬垫的杠杆上。","抓住机器的手柄或侧面以保持稳定性。","保持上半身静止，呼气并尽可能向上弯曲双腿，但不要将臀部抬离垫子。","挤压腿筋时，保持收缩位置短暂停顿。","吸气并缓慢地将控制杆降低回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0592","name":"lever preacher curl","nameZh":"器械牧师凳弯举","equipment":"leverage machine","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0592-b6hQYMb.jpg","gifPath":"exercises/videos/0592-b6hQYMb.gif","instructionSteps":["调整座椅高度并将自己放在杠杆机上。","将上臂放在垫子上，并用反手握住手柄。","保持背部挺直，并将肘部放在垫子上。","呼气并将前臂向上臂弯曲，收缩二头肌。","在动作的最高点暂停片刻，挤压你的二头肌。","吸气并慢慢将手柄放回起始位置。","重复所需的重复次数。"],"aliases":["器械牧师弯举"]},{"id":"0596","name":"lever seated fly","nameZh":"器械夹胸","equipment":"leverage machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0596-v3xmPAR.jpg","gifPath":"exercises/videos/0596-v3xmPAR.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在垫子上。","旋前抓住手柄，并保持肘部稍微弯曲。","呼气并将手柄向前推，将它们放在胸前。","暂停片刻，挤压胸部肌肉。","吸气并慢慢回到起始位置，让胸部肌肉伸展。","重复所需的重复次数。"],"aliases":["蝴蝶机飞鸟","pec deck"]},{"id":"0597","name":"lever seated hip abduction","nameZh":"器械髋外展","equipment":"leverage machine","bodyPart":"upper legs","target":"abductors","imagePath":"exercises/images/0597-CHpahtl.jpg","gifPath":"exercises/videos/0597-CHpahtl.gif","instructionSteps":["调整座椅高度，使膝盖成 90 度角。","坐在机器上，背部靠在靠背上，双脚放在脚踏板上。","将手放在侧手柄上以保持稳定性。","启动外展肌并慢慢将双腿分开，远离身体中线。","动作结束时暂停片刻，然后慢慢将双腿放回到起始位置。","重复所需的重复次数。"],"aliases":["坐姿髋外展"]},{"id":"0598","name":"lever seated hip adduction","nameZh":"器械髋内收","equipment":"leverage machine","bodyPart":"upper legs","target":"adductors","imagePath":"exercises/images/0598-oHsrypV.jpg","gifPath":"exercises/videos/0598-oHsrypV.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在靠背上。","将脚放在脚踏板上并抓住手柄以保持稳定。","收紧内收肌，慢慢将双腿并拢，挤压大腿内侧。","在收缩高峰时暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"],"aliases":["坐姿髋内收","腿内收"]},{"id":"0599","name":"lever seated leg curl","nameZh":"器械坐姿腿弯举","equipment":"leverage machine","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0599-Zg3XY7P.jpg","gifPath":"exercises/videos/0599-Zg3XY7P.gif","instructionSteps":["调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。","将小腿放在带衬垫的杠杆下方，就在脚踝上方。","抓住机器两侧的手柄以提供支撑。","保持大腿不动，呼气并尽可能向上弯曲双腿。","挤压腿筋时，保持收缩位置短暂停顿。","吸气并缓慢地将控制杆降低回起始位置。","重复所需的重复次数。"],"aliases":["坐姿腿弯举"]},{"id":"0602","name":"lever seated reverse fly","nameZh":"器械反向飞鸟","equipment":"leverage machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0602-myfUsKf.jpg","gifPath":"exercises/videos/0602-myfUsKf.gif","instructionSteps":["调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。","正手握住手柄，并保持手臂稍微弯曲。","呼气并将肩胛骨挤压在一起，同时向后和向外拉动手柄，使其远离身体。","在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。","重复所需的重复次数。"],"aliases":["蝴蝶机反向飞鸟"]},{"id":"0603","name":"lever shoulder press","nameZh":"器械肩推","equipment":"leverage machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0603-67n3r98.jpg","gifPath":"exercises/videos/0603-67n3r98.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在靠背上。","正手握住手柄，并将双手置于肩部水平。","向上推动手柄，直到手臂完全伸展，但不要锁住肘部。","在顶部暂停片刻，然后慢慢将手柄放回起始位置。","重复所需的重复次数。"],"aliases":["器械推举"]},{"id":"0605","name":"lever standing calf raise","nameZh":"站姿提踵","equipment":"leverage machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0605-ykUOVze.jpg","gifPath":"exercises/videos/0605-ykUOVze.gif","instructionSteps":["将机器调整到您的高度，双脚分开与肩同宽站立。","将肩膀放在护垫下方，并握住手柄以保持稳定。","伸展脚踝，将脚后跟尽可能抬高。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"],"aliases":["器械站姿提踵"]},{"id":"0606","name":"lever t bar row","nameZh":"T 杆划船","equipment":"leverage machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0606-aaXr7ld.jpg","gifPath":"exercises/videos/0606-aaXr7ld.gif","instructionSteps":["调整座椅高度和踏板位置以确保正确对齐。","坐在机器上，胸部靠在垫子上，双脚平放在踏板上。","正手握住手柄，握距略宽于肩宽。","保持背部挺直并启动核心肌群。","将手柄拉向躯干，将肩胛骨挤压在一起。","在收缩峰值时暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"],"aliases":["T 杠划船"]},{"id":"0607","name":"lever triceps extension","nameZh":"器械臂屈伸","equipment":"leverage machine","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0607-Ser9eQp.jpg","gifPath":"exercises/videos/0607-Ser9eQp.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在垫子上。","正手握住手柄，并将手臂完全伸展到身前。","保持上臂不动，弯曲肘部，慢慢将手柄向前额降低。","在底部暂停片刻，然后伸展双臂将手柄推回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0620","name":"lying leg raise flat bench","nameZh":"仰卧举腿","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0620-WhuFnR7.jpg","gifPath":"exercises/videos/0620-WhuFnR7.gif","instructionSteps":["平躺在平坦的长凳上，背部紧贴长凳。","将双手放在臀部下方以获得支撑。","保持双腿伸直并拢，然后将它们抬向天花板。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"],"aliases":["躺姿抬腿"]},{"id":"0624","name":"march sit (wall)","nameZh":"靠墙坐姿行军","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0624-sVQCCeG.jpg","gifPath":"exercises/videos/0624-sVQCCeG.gif","instructionSteps":["背靠墙站立，双脚分开与臀部同宽。","慢慢地将背部滑下墙壁，直到膝盖弯曲成 90 度角。","将右脚抬离地面，并将膝盖靠近胸部。","将右脚放低，将左脚抬离地面，将膝盖靠近胸部。","继续交替抬起右脚和左脚，达到所需的重复次数。"],"aliases":["靠墙静蹲抬膝"]},{"id":"0628","name":"monster walk","nameZh":"怪物行走","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0628-O95afRA.jpg","gifPath":"exercises/videos/0628-O95afRA.gif","instructionSteps":["在脚踝周围放置一根阻力带。","双脚分开与肩同宽站立，稍微弯曲膝盖。","右脚向一侧迈出一步，保持阻力带的张力。","左脚跟随，向一侧迈步以返回起始位置。","重复所需的重复次数，然后换边。"],"aliases":["弹力带侧走","螃蟹步"]},{"id":"0652","name":"pull-up","nameZh":"引体向上","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0652-lBDjFxJ.jpg","gifPath":"exercises/videos/0652-lBDjFxJ.gif","instructionSteps":["悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。","启动你的核心并将肩胛骨挤压在一起。","弯曲肘部并将胸部拉向杠铃杆，将身体向上拉向杠铃杆。","在动作的最高点暂停，然后慢慢降低身体回到起始位置。","重复所需的重复次数。"],"aliases":["正手引体"]},{"id":"0659","name":"push-up (wall)","nameZh":"靠墙俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0659-LEH9jxP.jpg","gifPath":"exercises/videos/0659-LEH9jxP.gif","instructionSteps":["面向墙壁站立，距离大约一臂距离。","将双手放在墙上，与肩同高，距离略宽于肩宽。","后退几英尺，保持身体挺直，双脚分开与臀部同宽。","弯曲肘部，将胸部向墙壁降低，保持身体呈一条直线。","推回起始位置，伸直手臂。","重复所需的重复次数。"],"aliases":["墙壁俯卧撑"]},{"id":"0662","name":"push-up","nameZh":"俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0662-I4hDWkc.jpg","gifPath":"exercises/videos/0662-I4hDWkc.gif","instructionSteps":["从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。","弯曲肘部，调动核心力量，将身体压向地面，保持身体呈一条直线。","当你的胸部刚好高于地面时，暂停片刻，然后伸直手臂，将自己推回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0687","name":"russian twist","nameZh":"俄罗斯转体","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0687-XVDdcoj.jpg","gifPath":"exercises/videos/0687-XVDdcoj.gif","instructionSteps":["坐在地上，膝盖弯曲，双脚平放在地板上。","稍微向后倾斜，同时保持背部挺直并且核心参与。","如果需要，双手合拢放在胸前或举重物。","将脚抬离地面，在坐骨上保持平衡。","将你的躯干向右扭转，将你的手或重量移向身体的右侧。","暂停片刻，然后将躯干向左扭转，将手或体重移向身体的左侧。","继续交替进行所需的重复次数。"],"aliases":[]},{"id":"0688","name":"scapular pull-up","nameZh":"肩胛引体","equipment":"body weight","bodyPart":"back","target":"traps","imagePath":"exercises/images/0688-uTBt1HV.jpg","gifPath":"exercises/videos/0688-uTBt1HV.gif","instructionSteps":["首先悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。","通过向下拉和向后拉动肩胛骨来缩回肩胛骨。","启动背部肌肉，将身体拉向杠铃杆，重点是将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢降低身体回到起始位置。","重复所需的重复次数。"],"aliases":["肩胛下沉","Scapular Pull-up"]},{"id":"0705","name":"side bridge v. 2","nameZh":"侧平板支撑","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0705-RKjH6Lt.jpg","gifPath":"exercises/videos/0705-RKjH6Lt.gif","instructionSteps":["侧躺，双腿伸展并叠放在一起。","将前臂放在肩膀正下方的地面上，肘部弯曲成 90 度角。","启动你的核心并将臀部抬离地面，从头到脚形成一条直线。","保持此位置所需的时间。","将臀部放低至起始位置。","在另一侧重复。"],"aliases":["侧桥支撑"]},{"id":"0710","name":"side hip abduction","nameZh":"站姿髋外展","equipment":"body weight","bodyPart":"upper legs","target":"abductors","imagePath":"exercises/images/0710-7WaDzyL.jpg","gifPath":"exercises/videos/0710-7WaDzyL.gif","instructionSteps":["双脚分开与肩同宽站立，双手放在臀部。","将重心转移到一条腿上，并将另一条腿向一侧抬起，保持伸直。","在顶部暂停片刻，然后慢慢将腿放回起始位置。","在另一侧重复。","继续交替进行所需的重复次数。"],"aliases":["自重髋外展"]},{"id":"0735","name":"sit-up v. 2","nameZh":"仰卧起坐","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0735-Bn6TXyO.jpg","gifPath":"exercises/videos/0735-Bn6TXyO.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0739","name":"sled 45в° leg press","nameZh":"腿举","equipment":"sled machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0739-10Z2DXU.jpg","gifPath":"exercises/videos/0739-10Z2DXU.gif","instructionSteps":["将雪橇机的座椅和脚踏板调整到舒适的位置。","坐在雪橇机上，背部靠在靠背上，双脚与肩同宽放在踏板上。","握住座椅两侧的把手以保持稳定性。","伸展双腿，将脚踏板推离身体，脚后跟保持在脚踏板上。","继续推动，直到双腿几乎完全伸展，但不要锁住膝盖。","在动作的最高点暂停片刻，然后弯曲膝盖，慢慢地将踏板放回到身体的方向。","重复所需的重复次数。"],"aliases":["倒蹬","器械倒蹬","45°腿举"]},{"id":"0743","name":"sled hack squat","nameZh":"雪橇机哈克深蹲","equipment":"sled machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0743-Qa55kX1.jpg","gifPath":"exercises/videos/0743-Qa55kX1.gif","instructionSteps":["将雪橇机调整到适合您身高的舒适位置。","双脚与肩同宽站立在平台上，脚趾稍微向外。","握住手柄或杆以保持稳定性。","弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。","继续降低，直到大腿与地面平行或略低于地面。","暂停片刻，然后用脚后跟将身体抬回到起始位置。","重复所需的重复次数。"],"aliases":["哈克机深蹲"]},{"id":"0748","name":"smith bench press","nameZh":"史密斯卧推","equipment":"smith machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0748-trqKQv2.jpg","gifPath":"exercises/videos/0748-trqKQv2.gif","instructionSteps":["将史密斯机杆的高度调整至胸部水平。","平躺在长凳上，双脚牢牢踩在地上。","正手握住杠铃，握距略宽于肩宽。","松开杠铃并将其向胸部降低，保持肘部内收。","当杠铃接触到你的胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"aliases":["史密斯机卧推"]},{"id":"0757","name":"smith incline bench press","nameZh":"史密斯上斜卧推","equipment":"smith machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0757-5v7KYld.jpg","gifPath":"exercises/videos/0757-5v7KYld.gif","instructionSteps":["将长凳调整至 30-45 度倾斜。","坐在长凳上，背部平放在垫子上，双脚牢牢踩在地上。","正手握住杠铃，握距略宽于肩宽。","松开杠铃，慢慢地将其降低到上胸部，保持肘部稍微内收。","在底部停顿片刻，然后将杠铃推回起始位置，充分伸展双臂。","重复所需的重复次数。"],"aliases":["史密斯机上斜卧推"]},{"id":"0766","name":"smith shoulder press","nameZh":"史密斯肩推","equipment":"smith machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0766-903mzG8.jpg","gifPath":"exercises/videos/0766-903mzG8.gif","instructionSteps":["调整座椅高度，将自己放在史密斯机上，双脚分开与肩同宽。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其置于与肩同高的位置，肘部弯曲，手掌朝前。","向上推杠铃，直到手臂完全伸过头顶。","在顶部暂停片刻，然后慢慢将杠铃放回至肩部水平。","重复所需的重复次数。"],"aliases":["史密斯机肩推"]},{"id":"0770","name":"smith squat","nameZh":"史密斯深蹲","equipment":"smith machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0770-jFtipLl.jpg","gifPath":"exercises/videos/0770-jFtipLl.gif","instructionSteps":["将史密斯机和杠铃设置在适合深蹲的高度。","站立，双脚分开与肩同宽，脚趾稍微向外。","将自己置于杠铃下方，将其放在斜方肌上部和肩膀上。","宽握距握住杠铃，握距略宽于肩宽。","启动你的核心并打开杠铃，后退以清理架子。","保持胸部挺直，背部挺直，通过弯曲臀部和膝盖开始深蹲。","降低身体，直到大腿与地面平行或稍低于地面。","在底部停顿片刻，然后用脚后跟恢复到起始位置。","重复所需的重复次数。"],"aliases":["史密斯机深蹲"]},{"id":"0814","name":"triceps dip","nameZh":"肱三头肌臂屈伸","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0814-X6C6i5Y.jpg","gifPath":"exercises/videos/0814-X6C6i5Y.gif","instructionSteps":["坐在长凳或椅子的边缘，双手抓住边缘，手指指向前方。","将臀部滑离长凳，用手支撑体重。","弯曲肘部，将身体放低至地面，保持背部靠近长凳。","在底部暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"],"aliases":["双杠三头臂屈伸"]},{"id":"0861","name":"cable seated row","nameZh":"坐姿划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0861-fUBheHs.jpg","gifPath":"exercises/videos/0861-fUBheHs.gif","instructionSteps":["坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手握住手柄，保持背部挺直，肩膀放松。","将手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"],"aliases":["坐姿绳索划船","低位划船"]},{"id":"0864","name":"dumbbell upright shoulder external rotation","nameZh":"哑铃站姿肩外旋","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0864-x306lCW.jpg","gifPath":"exercises/videos/0864-x306lCW.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","将手臂向两侧抬起，直到与地面平行，保持肘部稍微弯曲。","向外旋转手臂，将哑铃举向头部，同时保持肘部处于同一位置。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"aliases":["哑铃肩袖外旋","站姿哑铃外旋"]},{"id":"0868","name":"cable curl","nameZh":"绳索弯举","equipment":"cable","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0868-G08RZcQ.jpg","gifPath":"exercises/videos/0868-G08RZcQ.gif","instructionSteps":["面对电缆机站立，双脚与肩同宽。","用手握住电缆附件，手掌朝上。","保持肘部靠近身体两侧，上臂保持静止。","呼气并将电缆附件卷向肩膀，收缩二头肌。","在动作的最高点暂停片刻，挤压你的二头肌。","吸气并缓慢地将电缆附件放回起始位置。","重复所需的重复次数。"],"aliases":["龙门架弯举","直杆绳索弯举"]},{"id":"0872","name":"reverse crunch","nameZh":"反向卷腹","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0872-nCU1Ekp.jpg","gifPath":"exercises/videos/0872-nCU1Ekp.gif","instructionSteps":["平躺，双臂沿着身体两侧伸展。","弯曲膝盖，将脚抬离地面，使大腿垂直于地板。","收缩腹肌，将臀部卷离地板，使膝盖靠近胸部。","在顶部暂停片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"],"aliases":[]},{"id":"0979","name":"band horizontal pallof press","nameZh":"水平弹力带 Pallof 推","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0979-9pa4H5m.jpg","gifPath":"exercises/videos/0979-9pa4H5m.gif","instructionSteps":["将带子固定在腰部高度的坚固锚点上。","垂直于锚点站立，双脚分开与肩同宽。","用双手抓住带子手柄并远离锚点以在带子中产生张力。","将双手放在胸前，保持肘部弯曲并靠近身体。","调动你的核心并保持稳定的姿势。","将手臂伸直至前方，将弹力带推离身体。","保持伸展姿势几秒钟，专注于保持核心紧张。","慢慢地将双手放回胸前，抵抗弹力带的拉力。","重复所需的重复次数。"],"aliases":["水平 Pallof","抗旋转推"]},{"id":"0993","name":"band reverse fly","nameZh":"弹力带拉开","equipment":"band","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0993-sTfvVsG.jpg","gifPath":"exercises/videos/0993-sTfvVsG.gif","instructionSteps":["将带子固定在胸部高度的固定物体上。","双脚分开与肩同宽站立，双手握住弹力带放在身前。","保持手臂伸直并将其向两侧抬起，直到与地面平行。","在动作的最高点将肩胛骨挤压在一起。","慢慢地将手臂放回起始位置。","重复所需的重复次数。"],"aliases":["弹力带反向飞鸟","水平扩胸"]},{"id":"1017","name":"band y-raise","nameZh":"弹力带 Y 字举","equipment":"band","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/1017-aHDy5O5.jpg","gifPath":"exercises/videos/1017-aHDy5O5.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝内。","保持双臂伸直，将其向上举至两侧，与身体形成“Y”形。","在动作的最高点将肩胛骨挤压在一起。","慢慢地将手臂放回起始位置。","重复所需的重复次数。"],"aliases":["弹力带 Y raise","肩胛 Y 举"]},{"id":"1299","name":"lever incline chest press","nameZh":"器械上斜推胸","equipment":"leverage machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1299-jHAnWmT.jpg","gifPath":"exercises/videos/1299-jHAnWmT.gif","instructionSteps":["将杠杆机的座椅和靠背调整到舒适的位置。","坐在机器上，背部靠在靠背上，双脚平放在地板上。","正手握住手柄，双手之间的距离略大于肩宽。","向前推动手柄并使其远离身体，直到双臂完全伸展。","暂停片刻，然后慢慢弯曲肘部，将手柄放回到胸部。","重复所需的重复次数。"],"aliases":[]},{"id":"1326","name":"chin-up","nameZh":"反握引体向上","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/1326-T2mxWqc.jpg","gifPath":"exercises/videos/1326-T2mxWqc.gif","instructionSteps":["悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。","启动核心肌群，将身体拉向杠铃杆，以胸部为主导。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"aliases":["反手引体","chin-up"]},{"id":"1350","name":"lever seated row","nameZh":"器械坐姿划船","equipment":"leverage machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1350-7I6LNUG.jpg","gifPath":"exercises/videos/1350-7I6LNUG.gif","instructionSteps":["将座椅高度和脚踏板调整到舒适的位置。","坐在机器上，胸部靠在垫子上，双脚放在脚踏板上。","正手握住手柄，距离与肩同宽。","保持背部挺直，核心肌群参与。","将手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点停顿片刻。","慢慢松开手柄并返回到起始位置。","重复所需的重复次数。"],"aliases":["坐姿器械划船"]},{"id":"1361","name":"smith reverse grip bent over row","nameZh":"史密斯反手划船","equipment":"smith machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1361-aaxA3cm.jpg","gifPath":"exercises/videos/1361-aaxA3cm.gif","instructionSteps":["将史密斯机设置为与臀部高度相同的杠铃。","面向杠铃站立，双脚分开与肩同宽。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","反手握住杠铃，双手与肩同宽。","将杠铃拉向下胸部，将肩胛骨挤压在一起。","在顶部暂停片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"aliases":["史密斯机反手划船"]},{"id":"1409","name":"barbell glute bridge","nameZh":"杠铃臀桥","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1409-qKBpF7I.jpg","gifPath":"exercises/videos/1409-qKBpF7I.gif","instructionSteps":["首先平躺在地上，膝盖弯曲，双脚平放在地板上。","将杠铃放在臀部上，用双手牢牢握住它。","锻炼臀部和核心肌肉，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。","在顶部暂停片刻，挤压臀部。","慢慢地将臀部放回起始位置。","重复所需的重复次数。"],"aliases":["负重臀桥"]},{"id":"1457","name":"barbell standing wide military press","nameZh":"杠铃推举","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/1457-Kyd9Rz5.jpg","gifPath":"exercises/videos/1457-Kyd9Rz5.gif","instructionSteps":["双脚分开与肩同宽站立，正手握杠铃，握距略宽于肩。","将杠铃举至肩膀高度，保持肘部稍微位于杠铃前方。","将杠铃推过头顶，充分伸展双臂。","将杠铃降低回肩部高度，然后重复所需的重复次数。"],"aliases":["站姿推举","实力推","过顶推"]},{"id":"1460","name":"walking lunge","nameZh":"弓步蹲","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1460-IZVHb27.jpg","gifPath":"exercises/videos/1460-IZVHb27.gif","instructionSteps":["双脚分开与肩同宽站立。","右腿向前迈出一步，将身体降低至弓步位置。","保持躯干直立，前膝与脚踝对齐。","右脚蹬地，左脚向前，左腿呈弓步姿势。","继续交替双腿向前行走，保持受控且稳定的步伐。","重复所需的重复次数。"],"aliases":["行走箭步蹲","walking lunge"]},{"id":"1604","name":"world greatest stretch","nameZh":"世界最伟大拉伸","equipment":"body weight","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/1604-DFGXwZr.jpg","gifPath":"exercises/videos/1604-DFGXwZr.gif","instructionSteps":["从弓步位置开始，右脚向前，左脚向后。","将双手放在右脚两侧的地面上。","将左膝降低到地面并伸展右腿，保持右脚平放在地面上。","向右旋转你的躯干，将你的右臂伸向天花板。","保持这个姿势几秒钟，然后回到起始位置。","换边并重复拉伸，左脚向前。"],"aliases":["伟大拉伸","World’s Greatest Stretch"]},{"id":"1757","name":"dumbbell single leg deadlift","nameZh":"单腿硬拉","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1757-gKozT8X.jpg","gifPath":"exercises/videos/1757-gKozT8X.gif","instructionSteps":["双脚分开与臀部同宽站立，右手握住哑铃。","将体重转移到左腿上，并将右脚稍微抬离地面。","保持背部挺直，臀部向前转动，将哑铃放低至地面。","同时，将右腿伸直在身后，保持左膝轻微弯曲。","降低哑铃，直到躯干和右腿与地面平行。","暂停片刻，然后收紧臀肌和腿筋，回到起始位置。","重复所需的重复次数，然后换边。"],"aliases":["单腿罗马尼亚硬拉","哑铃单腿硬拉"]},{"id":"1760","name":"dumbbell goblet squat","nameZh":"哑铃高脚杯深蹲","equipment":"dumbbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/1760-yn8yg1r.jpg","gifPath":"exercises/videos/1760-yn8yg1r.gif","instructionSteps":["双脚分开与肩同宽站立，双手握住哑铃垂直放在胸前。","保持胸部挺直，核心收紧，通过向后推臀部并弯曲膝盖，将身体降低至蹲姿。","继续降低，直到大腿与地面平行，或者尽可能低。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"aliases":["高脚杯深蹲"]},{"id":"2133","name":"farmers walk","nameZh":"农夫行走","equipment":"dumbbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/2133-qPEzJjA.jpg","gifPath":"exercises/videos/2133-qPEzJjA.gif","instructionSteps":["站直，双手各握一个哑铃，手掌朝向身体两侧。","保持背部挺直，肩膀向后。","向前迈出小步，控制住，保持直立姿势。","继续步行所需的距离或时间。","最后，停止行走并小心地将哑铃降低到身体两侧。"],"aliases":["农夫走","Farmer’s Walk"]},{"id":"2137","name":"dumbbell arnold press","nameZh":"哑铃阿诺德推举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/2137-Xy4jlWA.jpg","gifPath":"exercises/videos/2137-Xy4jlWA.gif","instructionSteps":["坐在有背部支撑的长凳上，双手各握一个哑铃，与肩同高，手掌朝向身体，肘部弯曲。","向上推哑铃，直到手臂完全伸展，手掌朝前。","抬起时旋转手腕，使手掌在动作的最高点朝前。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"aliases":["阿诺德推举"]},{"id":"2143","name":"dumbbell standing around world","nameZh":"哑铃肩绕环","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/2143-RSOsp5d.jpg","gifPath":"exercises/videos/2143-RSOsp5d.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","将手臂伸直至两侧，与肩同高，手掌朝下。","保持手臂伸直，慢慢地以圆周运动旋转手臂，将哑铃放在身体前面，然后举过头顶。","继续圆周运动，将哑铃放回起始位置。","重复所需的重复次数。"],"aliases":["哑铃绕肩","Around the World"]},{"id":"2188","name":"dumbbell seated triceps extension","nameZh":"哑铃颈后臂屈伸","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/2188-kont8Ut.jpg","gifPath":"exercises/videos/2188-kont8Ut.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","双手握住哑铃，双臂伸直举过头顶。","弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。","暂停片刻，然后伸直手臂，回到起始位置。","重复所需的重复次数。"],"aliases":["坐姿哑铃臂屈伸","哑铃过头臂屈伸"]},{"id":"2292","name":"dumbbell rear delt raise","nameZh":"俯身哑铃飞鸟","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/2292-mu5Guxt.jpg","gifPath":"exercises/videos/2292-mu5Guxt.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"],"aliases":["俯身反向飞鸟","俯身哑铃侧平举"]},{"id":"2368","name":"split squats","nameZh":"保加利亚分腿蹲","equipment":"body weight","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/2368-9E25EOx.jpg","gifPath":"exercises/videos/2368-9E25EOx.gif","instructionSteps":["双脚分开与肩同宽站立。","一只脚向前迈出一步，并将其放在另一只脚前面约两英尺处。","弯曲膝盖和臀部，降低身体，保持背部挺直。","继续降低，直到前大腿与地面平行，后膝盖悬停在地面上方。","暂停片刻，然后推动前脚跟回到起始位置。","重复所需的重复次数，然后换腿并重复。"],"aliases":["保加利亚深蹲","分腿蹲"]},{"id":"2616","name":"cable lateral pulldown with v-bar","nameZh":"V 杆窄距高位下拉","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/2616-4c9BhzB.jpg","gifPath":"exercises/videos/2616-4c9BhzB.gif","instructionSteps":["坐在电缆下拉机上，用正手抓住 V 形杆附件。","调整护膝，使大腿固定在其下方。","保持背部挺直并稍微向后倾斜。","将 V 形杆向下拉至上胸部，同时保持肘部靠近身体。","在动作底部挤压背部肌肉。","慢慢地将 v 形杆返回到起始位置，然后重复所需的重复次数。"],"aliases":["V 杆下拉","窄距下拉"]},{"id":"3006","name":"resistance band seated hip abduction","nameZh":"弹力带坐姿髋外展","equipment":"resistance band","bodyPart":"upper legs","target":"abductors","imagePath":"exercises/images/3006-0xDpB4L.jpg","gifPath":"exercises/videos/3006-0xDpB4L.gif","instructionSteps":["坐在椅子或长凳上，背部挺直，双脚平放在地面上。","将阻力带缠绕在大腿上，就在膝盖上方。","将双手放在椅子或长凳的两侧以获得支撑。","启动外展肌（大腿外侧肌肉），并克服弹力带的阻力，慢慢将膝盖分开。","动作结束时暂停片刻，然后慢慢将膝盖放回一起。","重复所需的重复次数。"],"aliases":["弹力带髋外展"]},{"id":"3011","name":"incline scapula push up","nameZh":"上斜肩胛俯卧撑","equipment":"body weight","bodyPart":"chest","target":"serratus anterior","imagePath":"exercises/images/3011-GdMa1ET.jpg","gifPath":"exercises/videos/3011-GdMa1ET.gif","instructionSteps":["设置一个 45 度角的上斜凳。","将双手放在长凳上，距离略比肩宽。","将双脚放在地面上，距离与臀部同宽。","将胸部向长凳方向降低，保持肘部内收。","当你降低时，缩回肩胛骨，将肩胛骨挤压在一起。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"],"aliases":["上斜肩胛推","入门肩胛俯卧撑"]},{"id":"3012","name":"scapula dips","nameZh":"站姿肩胛后缩撑起","equipment":"body weight","bodyPart":"back","target":"traps","imagePath":"exercises/images/3012-7xeukSt.jpg","gifPath":"exercises/videos/3012-7xeukSt.gif","instructionSteps":["首先站立，双脚分开与肩同宽，双臂在身前伸展。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","弯曲肘部并缩回肩胛骨来降低身体，就像你试图在它们之间挤一支铅笔一样。","在底部停顿片刻，然后双手用力，伸展肘部，回到起始位置。","重复所需的重复次数。"],"aliases":["肩胛后缩","肩胛控制"]},{"id":"3013","name":"low glute bridge on floor","nameZh":"臀桥","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/3013-u0cNiij.jpg","gifPath":"exercises/videos/3013-u0cNiij.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将手臂放在身体两侧，手掌朝下。","启动臀肌和核心肌群，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。","在顶部暂停片刻，挤压臀部。","慢慢地将臀部放回起始位置。","重复所需的重复次数。"],"aliases":["自重臀桥","地面臀桥"]},{"id":"3021","name":"scapula push-up","nameZh":"肩胛俯卧撑","equipment":"body weight","bodyPart":"chest","target":"serratus anterior","imagePath":"exercises/images/3021-jV65tKx.jpg","gifPath":"exercises/videos/3021-jV65tKx.gif","instructionSteps":["从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。","将胸部压向地面，保持肘部靠近身体。","当你下降时，将肩胛骨挤压在一起并将胸部向前推。","在底部停顿片刻，然后推回到起始位置。","重复所需的重复次数。"],"aliases":["前锯肌俯卧撑"]},{"id":"3561","name":"glute bridge march","nameZh":"臀桥行军","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/3561-GibBPPg.jpg","gifPath":"exercises/videos/3561-GibBPPg.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","收紧臀部并将臀部抬离地面，从膝盖到肩膀形成一条直线。","在保持臀部抬起的同时，将一只脚抬离地面，并将膝盖靠近胸部。","将脚放回地面，然后用另一条腿重复该动作。","继续交替双腿进行行进动作，同时保持桥式姿势。","重复所需的重复次数。"],"aliases":["交替臀桥","臀桥抬膝"]},{"id":"3699","name":"shoulder tap","nameZh":"交替触肩","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/3699-yRpV5TC.jpg","gifPath":"exercises/videos/3699-yRpV5TC.gif","instructionSteps":["从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。","启动你的核心并将右手抬离地面，伸手拍打你的左肩。","将右手放回地面，然后用左手轻拍右肩，重复此操作。","继续交替轻拍肩膀，同时保持臀部和躯干稳定。","重复所需的重复次数。"],"aliases":["肩碰肩","Shoulder Tap"]}];
